    // supply prefetch metadata for its response.
    const prerenderedRoute =
      routeModule.isDev ||
      isRouteCacheOwner(
        resolvedPathname,
        routeModule.cacheOwner,
        prerenderManifest.routes[resolvedPathname]
      )
        ? prerenderManifest.routes[resolvedPathname]
        : undefined
    const isPrerendered = Boolean(prerenderedRoute)

    const userAgent = req.headers['user-agent'] || ''
    const botType = getBotType(userAgent)

    /**
     * If true, this indicates that the request being made is for an app
     * prefetch request.
     */
    const isPrefetchRSCRequest =
      getRequestMeta(req, 'isPrefetchRSCRequest') ??
      // Runtime prefetches use the other values, so they're excluded.
      req.headers[NEXT_ROUTER_PREFETCH_HEADER] === NEXT_ROUTER_PREFETCH_STATIC

    // NOTE: Don't delete headers[RSC] yet, it still needs to be used in renderToHTML later

    const isRSCRequest =
      getRequestMeta(req, 'isRSCRequest') ??
      isRSCRequestHeader(req.headers[RSC_HEADER])

    const serverActionRequestMetadata = getServerActionRequestMetadata(req)
    const { isPossibleServerAction } = serverActionRequestMetadata

    // For subresource requests (e.g. images or fonts), return plain text 404
    // instead of rendering the not-found route.
    if (
      normalizedSrcPage === UNDERSCORE_NOT_FOUND_ROUTE &&
      (req.method === 'GET' || req.method === 'HEAD') &&
      !isRSCRequest &&
      isNonHtmlSecFetchDest(req.headers['sec-fetch-dest'])
    ) {
      res.statusCode = 404
      res.setHeader(
        'Cache-Control',
        'private, no-cache, no-store, max-age=0, must-revalidate'
      )
      res.setHeader('Content-Type', 'text/plain; charset=utf-8')
      res.end('Not Found')
      ctx.waitUntil?.(Promise.resolve())
      return null
    }

    /**
     * If the route being rendered is an app page, and the ppr feature has been
     * enabled, then the given route _could_ support PPR.
     */
    const couldSupportPPR: boolean = Boolean(nextConfig.cacheComponents)

    // Stash postponed state for server actions when in minimal mode.
    // We extract it here so the RDC is available for the re-render after the action completes.
    const resumeStateLengthHeader = req.headers[NEXT_RESUME_STATE_LENGTH_HEADER]
    if (
      !getRequestMeta(req, 'postponed') &&
      isMinimalMode &&
      couldSupportPPR &&
      isPossibleServerAction &&
      resumeStateLengthHeader &&
      typeof resumeStateLengthHeader === 'string'
    ) {
      const stateLength = parseInt(resumeStateLengthHeader, 10)
      const { maxPostponedStateSize, maxPostponedStateSizeBytes } =
        getMaxPostponedStateSize(nextConfig.experimental.maxPostponedStateSize)

      if (!isNaN(stateLength) && stateLength > 0) {
        if (stateLength > maxPostponedStateSizeBytes) {
          res.statusCode = 413
          res.end(getPostponedStateExceededErrorMessage(maxPostponedStateSize))
          ctx.waitUntil?.(Promise.resolve())
          return null
        }

        // Calculate max total body size to prevent buffering excessively large
        // payloads before the action handler checks. We use stateLength (not
        // maxPostponedStateSizeBytes) so the postponed state doesn't eat into
        // the action body budget - it's already validated above.
        const defaultActionBodySizeLimit = '1 MB'
        const actionBodySizeLimit =
          nextConfig.experimental.serverActions?.bodySizeLimit ??
          defaultActionBodySizeLimit
        const actionBodySizeLimitBytes =
          actionBodySizeLimit !== defaultActionBodySizeLimit
            ? (
                require('next/dist/compiled/bytes') as typeof import('next/dist/compiled/bytes')
              ).parse(actionBodySizeLimit)
            : 1024 * 1024 // 1 MB
        const maxTotalBodySize = stateLength + actionBodySizeLimitBytes

        const fullBody = await readBodyWithSizeLimit(req, maxTotalBodySize)
        if (fullBody === null) {
          res.statusCode = 413
          res.end(
            `Request body exceeded limit. ` +
              `To configure the body size limit for Server Actions, see: https://nextjs.org/docs/app/api-reference/next-config-js/serverActions#bodysizelimit`
          )
          ctx.waitUntil?.(Promise.resolve())
          return null
        }

        if (fullBody.length >= stateLength) {
          // Extract postponed state from the beginning
          const postponedState = fullBody
            .subarray(0, stateLength)
            .toString('utf8')
          addRequestMeta(req, 'postponed', postponedState)

          // Store the remaining action body for the action handler
          const actionBody = fullBody.subarray(stateLength)
          addRequestMeta(req, 'actionBody', actionBody)
        } else {
          throw new Error(
            `invariant: expected ${stateLength} bytes of postponed state but only received ${fullBody.length} bytes`
          )
        }
      }
    }

    if (
      typeof getRequestMeta(req, 'postponed') !== 'string' &&
      couldSupportPPR &&
      req.headers[NEXT_RESUME_HEADER] === '1' &&
      req.method === 'POST'
    ) {
      const { maxPostponedStateSize, maxPostponedStateSizeBytes } =
        getMaxPostponedStateSize(nextConfig.experimental.maxPostponedStateSize)

      // Decode the postponed state from the request body, it will come as
      // an array of buffers, so collect them and then concat them to form
      // the string.
      const body = await readBodyWithSizeLimit(req, maxPostponedStateSizeBytes)
      if (body === null) {
        res.statusCode = 413
        res.end(getPostponedStateExceededErrorMessage(maxPostponedStateSize))
        ctx.waitUntil?.(Promise.resolve())
        return null
      }
      const postponed = body.toString('utf8')

      addRequestMeta(req, 'postponed', postponed)
    }

    // When enabled, this will allow the use of the `?__nextppronly` query to
    // enable debugging of the static shell.
    const hasDebugStaticShellQuery =
      process.env.__NEXT_EXPERIMENTAL_STATIC_SHELL_DEBUGGING === '1' &&
      typeof query.__nextppronly !== 'undefined' &&
      couldSupportPPR

    // When enabled, this will allow the use of the `?__nextppronly` query
    // to enable debugging of the fallback shell.
    const hasDebugFallbackShellQuery =
      hasDebugStaticShellQuery && query.__nextppronly === 'fallback'

    // Whether the testing API is exposed (dev mode or explicit flag)
    const exposeTestingApi =
      nextConfig.cacheComponents === true &&
      (routeModule.isDev === true ||
        nextConfig.experimental.exposeTestingApiInProductionBuild === true)

    // Enable the Instant Navigation Testing API. Renders only the prefetched
    // portion of the page, excluding dynamic content. This allows tests to
    // assert on the prefetched UI state deterministically.
    //
    // The instant test cookie is sent automatically with all requests while a
    // navigation lock is held. We treat a request as a test render when the
    // cookie is present and either:
    // - it's a document request (no RSC header) — covers MPA navigations
    // - it's a prefetch RSC request — covers client-side prefetches
    // Regular RSC navigation requests proceed normally even during a locked
    // scope; blocking happens on the client side.
    const isInstantNavigationTest =
      exposeTestingApi &&
      typeof req.headers.cookie === 'string' &&
      req.headers.cookie.includes(NEXT_INSTANT_TEST_COOKIE + '=') &&
      (!isRSCRequestHeader(req.headers[RSC_HEADER]) ||
        req.headers[NEXT_ROUTER_PREFETCH_HEADER] ===
          NEXT_ROUTER_PREFETCH_STATIC)

    // This page supports PPR if it is marked as being `PARTIALLY_STATIC` in the
    // prerender manifest and this is an app page.
    const isRoutePPREnabled: boolean =
      couldSupportPPR &&
      ((
        prerenderManifest.routes[normalizedSrcPage] ??
        prerenderManifest.dynamicRoutes[normalizedSrcPage]
      )?.renderingMode === 'PARTIALLY_STATIC' ||
        // Ideally we'd want to check the appConfig to see if this page has PPR
        // enabled or not, but that would require plumbing the appConfig through
        // to the server during development. We assume that the page supports it
        // but only during development or when the testing API is exposed.
        ((hasDebugStaticShellQuery || isInstantNavigationTest) &&
          (exposeTestingApi ||
            routerServerContext?.experimentalTestProxy === true)))

    const isDebugStaticShell: boolean =
      (hasDebugStaticShellQuery || isInstantNavigationTest) && isRoutePPREnabled

    // We should enable debugging dynamic accesses when the static shell
    // debugging has been enabled and we're also in development mode.
    const isDebugDynamicAccesses =
      isDebugStaticShell && routeModule.isDev === true

    const isDebugFallbackShell = hasDebugFallbackShellQuery && isRoutePPREnabled
    const isDebugPrerender =
      isDebugStaticShell || isDebugDynamicAccesses || isDebugFallbackShell

    // If we're in minimal mode, then try to get the postponed information from
    // the request metadata. If available, use it for resuming the postponed
    // render.
    const minimalPostponed = isRoutePPREnabled
      ? getRequestMeta(req, 'postponed')
      : undefined
    const hasPostponedState = typeof minimalPostponed === 'string'

    // If PPR is enabled, and this is a RSC request (but not a prefetch), then
    // we can use this fact to only generate the flight data for the request
    // because we can't cache the HTML (as it's also dynamic).
    const staticPrefetchDataRoute = prerenderedRoute?.prefetchDataRoute
    const isEnsureStaticPage = prerenderInfo?._isEnsureStaticPage === true

    let isDynamicRSCRequest =
      isRoutePPREnabled &&
      isRSCRequest &&
      !isPrefetchRSCRequest &&
      // If generated at build time, treat the RSC request as static
      // so we can serve the prebuilt .rsc without a dynamic render.
      // Only do this for routes that have a concrete prefetchDataRoute.
      !staticPrefetchDataRoute &&
      // Do not serve `ensureStatic = "navigation"` with a dynamic response,
      // (we want to do a blocking prerender instead)
      // TODO(ensure-static): express this in a cleaner way
      !isEnsureStaticPage

    // During a PPR revalidation, the RSC request is not dynamic if postponed
    // metadata is absent. An empty string represents a resume request without
    // postponed state, which should perform a full dynamic render.
    if (isMinimalMode) {
      isDynamicRSCRequest = isDynamicRSCRequest && hasPostponedState
    }

    // Need to read this before it's stripped by stripFlightHeaders. We don't
    // need to transfer it to the request meta because it's only read
    // within this function; the static segment data should have already been
    // generated, so we will always either return a static response or a 404.
    const rawSegmentPrefetchHeader =
      req.headers[NEXT_ROUTER_SEGMENT_PREFETCH_HEADER]
    const segmentPrefetchHeader =
      getRequestMeta(req, 'segmentPrefetchRSCRequest') ??
      (isPrefetchRSCRequest
        ? typeof rawSegmentPrefetchHeader === 'string'
          ? rawSegmentPrefetchHeader
          : Array.isArray(rawSegmentPrefetchHeader)
            ? rawSegmentPrefetchHeader[0]
            : undefined
        : undefined)

    // TODO: investigate existing bug with shouldServeStreamingMetadata always
    // being true for a revalidate due to modifying the base-server this.renderOpts
    // when fixing this to correct logic it causes hydration issue since we set
    // serveStreamingMetadata to true during export
    const serveStreamingMetadata = !userAgent
      ? true
      : shouldServeStreamingMetadata(userAgent, nextConfig.htmlLimitedBots)

    // A PPR shell has already closed its head before the dynamic render resumes.
    // Blocking metadata resolved during the resume would therefore be emitted
    // after the head, where HTML-limited bots cannot observe it. Bypass the
    // shell so blocking metadata is included in the initial document head.
    const shouldForceDynamicPPRRender =
      isRoutePPREnabled && !serveStreamingMetadata

    const isSSG = Boolean(
      (prerenderInfo ||
        isPrerendered ||
        prerenderManifest.routes[normalizedSrcPage]) &&
        !shouldForceDynamicPPRRender
    )

    // When a page supports cacheComponents, we can support RDC for Navigations
    const supportsRDCForNavigations =
      isRoutePPREnabled && nextConfig.cacheComponents === true

    // In development, we always want to generate dynamic HTML.
    const supportsDynamicResponse: boolean =
      // If we're in development, we always support dynamic HTML, unless it's
      // a data request, in which case we only produce static HTML.
      routeModule.isDev === true ||
      // If this is a draft mode request, it supports dynamic HTML.
      isDraftMode ||
      // If this is not SSG or does not have static paths, then it supports
      // dynamic HTML.
      !isSSG ||
      // If this request has provided postponed data, it supports dynamic
      // HTML.
      hasPostponedState ||
      // If this handler supports onCacheEntryV2, then we can only support
      // dynamic responses if it's a dynamic RSC request and not in minimal mode. If it
      // doesn't support it we must fallback to the default behavior.
      (supportsRDCForNavigations && getRequestMeta(req, 'onCacheEntryV2')
        ? // In minimal mode, we'll always want to generate a static response
          // which will generate the RDC for the route. When resuming a Dynamic
          // RSC request, we'll pass the minimal postponed data to the render
          // which will trigger the `supportsDynamicResponse` to be true.
          isDynamicRSCRequest && !isMinimalMode
        : // Otherwise, we can support dynamic responses if it's a dynamic RSC request.
          isDynamicRSCRequest)

    const remainingPrerenderableParams =
      prerenderInfo?.remainingPrerenderableParams ?? []
    const remainingFallbackRouteParams = nextConfig.cacheComponents
      ? (prerenderInfo?.fallbackRouteParams?.filter(
          (param) =>
            !remainingPrerenderableParams.some(
              (prerenderableParam) =>
                prerenderableParam.paramName === param.paramName
            )
        ) ?? [])
      : []
    // Concrete optional routes like `/optional-catchall` can still match their
    // generic shell entry (eg /optional-catchall/[[...slug]]) in the prerender manifest.
    // If the omitted param already resolved to a real prerendered path, keep serving that concrete result.
    const hasOmittedConcreteFallbackParam =
      isPrerendered &&
      remainingPrerenderableParams.some((param) => {
        const value = params?.[param.paramName]
        return value == null || (Array.isArray(value) && value.length === 0)
      })
    const hasUnresolvedRootFallbackParams =
      prerenderInfo?.fallback === null &&
      (prerenderInfo.fallbackRootParams?.length ?? 0) > 0

    // SSG writes and navigation RDC reads use the same shell key. Completion
    // uses the matched shell rather than the fully resolved pathname. A request
    // for `/prefix/c/foo` can complete `/prefix/[one]/[two]` to
    // `/prefix/c/[two]`. This avoids creating an entry for every value of
    // `two`.
    //
    // The completed-shell key also applies when unresolved root params require
    // a blocking render. A source shell cannot be shared across root branches.
    // Completion resolves the params into the key as follows:
    // - Root params and other prerenderable params use concrete values.
    // - Never-prerenderable params remain placeholders.
    // The values of those placeholder params must not partition the cache.
    const fallbackPathname = prerenderMatch
      ? typeof prerenderInfo?.fallback === 'string'
        ? prerenderInfo.fallback
        : prerenderMatch.source
      : null
    let shellCacheKey: string | null = null
    if (
      nextConfig.cacheComponents &&
      // A closed matcher has no fallback shell. Its generated outputs must
      // retain their concrete cache keys.
      prerenderInfo?.fallback !== false &&
      // Never-prerenderable params must stay out of the key even when Partial
      // Prefetching is disabled.
      (nextConfig.partialPrefetching ||
        remainingFallbackRouteParams.length > 0) &&
      fallbackPathname &&
      prerenderInfo?.fallbackRouteParams?.length &&
      !hasOmittedConcreteFallbackParam
    ) {
      const cacheKey = buildCompletedShellCacheKey(
        fallbackPathname,
        remainingPrerenderableParams,
        params
      )

      if (
        cacheKey !== fallbackPathname ||
        remainingFallbackRouteParams.length > 0
      ) {
        shellCacheKey = cacheKey
      }
    }

    let ssgCacheKey: string | null = null
    let usesShellCacheKey = false
    if (
      !isDraftMode &&
      isSSG &&
      !supportsDynamicResponse &&
      !isPossibleServerAction &&
      !hasPostponedState &&
      !isDynamicRSCRequest
    ) {
      if (shellCacheKey !== null) {
        // Normal fallback serving uses the source shell's separate cache
        // lookup. Explicit revalidation skips that path, so it must write the
        // source key here even when no params can be completed.
        if (shellCacheKey !== fallbackPathname || isOnDemandRevalidate) {
          ssgCacheKey = shellCacheKey
          usesShellCacheKey = true
        }
      } else {
        ssgCacheKey = resolvedPathname
      }
    }

    // the staticPathKey differs from ssgCacheKey since
    // ssgCacheKey is null in dev since we're always in "dynamic"
    // mode in dev to bypass the cache. It can also be null for partial
    // fallback shells that should remain shared and must not create a
    // param-specific ISR entry, but we still need to honor fallback handling.
    let staticPathKey = ssgCacheKey
    if (
      !staticPathKey &&
      (routeModule.isDev ||
        (isSSG &&
          pageIsDynamic &&
          prerenderInfo?.fallbackRouteParams?.length &&
          // Server action requests must not get a staticPathKey, otherwise they
          // enter the fallback rendering block below and return the cached HTML
          // shell with the action result appended, instead of responding with
          // just the RSC action result.
          !isPossibleServerAction))
    ) {
      staticPathKey = resolvedPathname
    }

    // If this is a request for an app path that should be statically generated
    // and we aren't in the edge runtime, strip the flight headers so it will
    // generate the static response.
    if (
      !routeModule.isDev &&
      !isDraftMode &&
      isSSG &&
      isRSCRequest &&
      !isDynamicRSCRequest
    ) {
      stripFlightHeaders(req.headers)
    }

    const ComponentMod = {
      ...entryBase,
      tree,
      handler,
      routeModule,
      __next_app__,
    }

    // Before rendering (which initializes component tree modules), we have to
    // set the reference manifests to our global store so Server Action's
    // encryption util can access to them at the top level of the page module.
    if (serverActionsManifest && clientReferenceManifest) {
      setManifestsSingleton({
        page: srcPage,
        clientReferenceManifest,
        serverActionsManifest,
      })
    }

    const method = req.method || 'GET'
    const tracer = getTracer()
    const activeSpan = tracer.getActiveScopeSpan()
    const isWrappedByNextServer = Boolean(
      routerServerContext?.isWrappedByNextServer
    )
    const render404 = async () => {
      // TODO: should route-module itself handle rendering the 404
      if (routerServerContext?.render404) {
        await routerServerContext.render404(req, res, parsedUrl, false)
      } else {
        res.statusCode = 404
        res.end('This page could not be found')
      }
      return null
    }

    try {
      const varyHeader = routeModule.getVaryHeader(
        resolvedPathname,
        interceptionRoutePatterns
      )
      res.setHeader('Vary', varyHeader)
      let parentSpan: Span | undefined
      const invokeRouteModule = async (
        span: Span | undefined,
        context: AppPageRouteHandlerContext,
        renderOperation: AppPageRenderOperation
      ) => {
        const nextReq = new NodeNextRequest(req)
        const nextRes = new NodeNextResponse(res)

        const result =
          renderOperation === 'prerender'
            ? routeModule.prerender(nextReq, nextRes, context)
            : routeModule.render(nextReq, nextRes, context)

        return result.finally(() => {
          if (!span) return

          span.setAttributes({
            'http.status_code': res.statusCode,
            'next.rsc': isRSCRequest,
          })

          if (res.statusCode && res.statusCode >= 500) {
            // For 5xx status codes: SHOULD be set to 'Error' span status.
            // x-ref: https://opentelemetry.io/docs/specs/semconv/http/http-spans/#status
            span.setStatus({
              code: SpanStatusCode.ERROR,
            })
            // For span status 'Error', SHOULD set 'error.type' attribute.
            span.setAttribute('error.type', res.statusCode.toString())
          }

          const rootSpanAttributes = tracer.getRootSpanAttributes()
          // We were unable to get attributes, probably OTEL is not enabled
          if (!rootSpanAttributes) {
            return
          }

          if (
            rootSpanAttributes.get('next.span_type') !==
            BaseServerSpan.handleRequest
          ) {
            console.warn(
              `Unexpected root span type '${rootSpanAttributes.get(
                'next.span_type'
              )}'. Please report this Next.js issue https://github.com/vercel/next.js`
            )
            return
          }

          const route =
            rootSpanAttributes.get('next.route') || normalizedSrcPage
          const name = isRSCRequest
            ? `RSC ${method} ${route}`
            : `${method} ${route}`

          span.setAttributes({
            'next.route': route,
            'http.route': route,
            'next.span_name': name,
          })
          span.updateName(name)

          // Propagate http.route to the parent span if one exists (e.g.
          // a platform-created HTTP span in adapter deployments).
          if (parentSpan && parentSpan !== span) {
            parentSpan.setAttribute('http.route', route)
            parentSpan.updateName(name)
          }
        })
      }

      const incrementalCache =
        getRequestMeta(req, 'incrementalCache') ||
        (await routeModule.getIncrementalCache(
          req,
          nextConfig,
          previewProps,
          prerenderManifest,
          isMinimalMode
        ))

      incrementalCache?.resetRequestCache()
      ;(globalThis as any).__incrementalCache = incrementalCache

      const doRender = async ({
        span,
        postponed,
        fallbackRouteParams,
        renderOperation,
        allowEmptyStaticShell,
      }: {
        span?: Span
        allowEmptyStaticShell?: boolean

        /**
         * The postponed data for this render. This is only provided when resuming
         * a render that has been postponed.
         */
        postponed: string | undefined

        /**
         * The unknown route params for this render.
         */
        fallbackRouteParams: OpaqueFallbackRouteParams | null

        renderOperation: AppPageRenderOperation
      }): Promise<ResponseCacheEntry | PrerenderFailure> => {
        // A static page may have stripped Flight headers before reaching this
        // render. Parse only when the response cache invokes the render.
        const parsedRequestHeaders: ParsedRequestHeaders = parseRequestHeaders(
          req.headers,
          {
            isRoutePPREnabled,
            previewModeId: previewProps?.previewModeId,
          }
        )
        const routeMatch: RouteMatch = { resolvedPathname }
        const dev: DevRenderContext | undefined = createDevRenderContext(req)
        const context: AppPageRouteHandlerContext = {
          requestUrl: req.url!,
          query,
          params,
          page: normalizedSrcPage,
          routeMatch,
          parsedRequestHeaders,
          serverActionRequestMetadata,
          sharedContext: {
            buildId,
            deploymentId,
            clientAssetToken,
          },
          dev,
          fallbackRouteParams,
          renderOpts: {
            App: () => null,
            Document: () => null,
            pageConfig: {},
            ComponentMod,
            Component: interopDefault(ComponentMod),

            params,
            routeModule,
            page: srcPage,
            postponed,
            allowEmptyStaticShell,
            serveStreamingMetadata,
            supportsDynamicResponse:
              renderOperation === 'render' &&
              (typeof postponed === 'string' || supportsDynamicResponse),
            buildManifest,
            nextFontManifest,
            reactLoadableManifest,
            subresourceIntegrityManifest,
            setCacheStatus: routerServerContext?.setCacheStatus,
            setIsrStatus: routerServerContext?.setIsrStatus,
            setReactDebugChannel: routerServerContext?.setReactDebugChannel,
            sendErrorsToBrowser: routerServerContext?.sendErrorsToBrowser,

            dir:
              process.env.NEXT_RUNTIME === 'nodejs'
                ? (require('path') as typeof import('path')).join(
                    /* turbopackIgnore: true */
                    process.cwd(),
                    routeModule.relativeProjectDir
                  )
                : `${process.cwd()}/${routeModule.relativeProjectDir}`,
            isDraftMode,
            botType,
            isOnDemandRevalidate,
            assetPrefix: routeModule.getAssetPrefixForRender(
              routerServerContext,
              nextConfig.assetPrefix
            ),
            nextConfigOutput: nextConfig.output,
            crossOrigin: nextConfig.crossOrigin,
            trailingSlash: nextConfig.trailingSlash,
            images: nextConfig.images,
            previewProps,
            enableTainting: nextConfig.experimental.taint,
            reactMaxHeadersLength: nextConfig.reactMaxHeadersLength,

            multiZoneDraftMode,
            prefetchHints: prefetchHintsManifest,
            // With dynamicParams = false, every parameter is restricted to the
            // paths generated at build time. Advertise this even for allowed
            // URLs. Read the current manifest here because dev updates it as
            // routes compile.
            notFoundParams:
              (routeModule.isDev
                ? getRequestMeta(req, 'devNotFoundParams')
                : undefined) ??
              prerenderManifest.dynamicRoutes[normalizedSrcPage]
                ?.notFoundParams ??
              (prerenderManifest.dynamicRoutes[normalizedSrcPage]?.fallback ===
              false
                ? routeParamNames
                : undefined),
            incrementalCache,
            cacheLifeProfiles: nextConfig.cacheLife,
            staticPageGenerationTimeout: nextConfig.staticPageGenerationTimeout,
            basePath: nextConfig.basePath,
            serverActions: nextConfig.experimental.serverActions,
            logServerFunctions:
              typeof nextConfig.logging === 'object' &&
              Boolean(nextConfig.logging.serverFunctions),

            ...(isDebugStaticShell ||
            isDebugDynamicAccesses ||
            isDebugFallbackShell
              ? {
                  isBuildTimePrerendering: true,
                  isDebugDynamicAccesses: isDebugDynamicAccesses,
                }
              : {}),
            cacheComponents: Boolean(nextConfig.cacheComponents),
            partialPrefetching: nextConfig.partialPrefetching,
            // A fallback shell can only be upgraded to a concrete version if at
            // least one of its fallback params is a `generateStaticParams`
            // candidate (`remainingPrerenderableParams`), and only when Partial
            // Prefetching is enabled (the upgrade itself is gated on it above).
            // This gates whether the per-segment prefetch responses are flagged
            // `isUpgradeableISRFallback`; without an upgrade to wait for, the
            // client should not retry the prefetch.
            isFallbackUpgradeable:
              Boolean(nextConfig.partialPrefetching) &&
              remainingPrerenderableParams.length > 0,
            validationLevel:
              nextConfig.experimental.instantInsights.validationLevel,
            experimental: {
              isRoutePPREnabled,
              expireTime: nextConfig.expireTime,
              staleTimes: nextConfig.experimental.staleTimes,
              dynamicOnHover: Boolean(nextConfig.experimental.dynamicOnHover),
              optimisticRouting: Boolean(
                nextConfig.experimental.optimisticRouting
              ),
              parallelRouteMetadata: Boolean(
                nextConfig.experimental.parallelRouteMetadata
              ),
              inlineCss: Boolean(nextConfig.experimental.inlineCss),
              prefetchInlining:
                nextConfig.experimental.prefetchInlining ?? false,
              authInterrupts: Boolean(nextConfig.experimental.authInterrupts),
              reactBrowserBailout: Boolean(
                nextConfig.experimental.reactBrowserBailout
              ),
              serverComponentsHmrCancellation: Boolean(
                nextConfig.experimental.serverComponentsHmrCancellation
              ),
              useCacheTimeout: nextConfig.experimental.useCacheTimeout,
